from collections import deque
from enum import IntEnum
import json
import os
from pathlib import Path
import more_itertools
from more_itertools import recipes

assert Path(recipes.__file__).resolve().is_relative_to(Path(os.environ['PROBE_COPY']).resolve())
tail=more_itertools.tail
results=[]


def eq(actual,expected):
    assert actual==expected,(repr(actual),repr(expected))


def raises(expected,function,same=None):
    try:
        function()
    except expected as exc:
        if same is not None:
            assert exc is same
        return exc
    else:
        raise AssertionError(f'{expected.__name__} not raised')


def check(name,function):
    try:
        detail=function()
        results.append({'id':name,'status':'pass','detail':detail})
    except Exception as exc:
        results.append({'id':name,'status':'fail','error':type(exc).__name__,'message':str(exc)})


class IndexCount:
    def __init__(self,value):
        self.value=value
    def __index__(self):
        return self.value


def negative_plain_integers():
    for factory in (lambda:[],lambda:[1,2,3],lambda:'abc',lambda:range(3),lambda:iter(()),lambda:iter([1,2,3])):
        for n in (-1,-3):
            raises(ValueError,lambda:tail(n,factory()))


def zero_counts():
    for source in ([],[1,2,3],(),(1,2,3),'','abc',b'abc',range(3)):
        eq(list(tail(0,source)),[])
        eq(list(tail(0,iter(source))),[])


def ordinary_counts_and_oversize():
    checked=0
    for source in ([],[1,2,3],(),(1,2,3),'','abcdef',b'abcdef',range(6),deque([1,2,3])):
        values=list(source)
        for n in (1,2,len(values),len(values)+4):
            expected=values[-n:] if n else []
            for candidate in (source,iter(source)):
                eq(list(tail(n,candidate)),expected)
                checked+=1
    return {'sized_unsized_results_checked':checked}


def integer_subclass_counts():
    class Count(int):
        pass
    class NamedCount(IntEnum):
        NEGATIVE=-1
        ZERO=0
        TWO=2
        LARGE=8
    for count in (Count(0),Count(2),Count(8),NamedCount.ZERO,NamedCount.TWO,NamedCount.LARGE):
        expected=list(deque(iter('abcdef'),maxlen=count))
        eq(list(tail(count,iter('abcdef'))),expected)
        eq(list(tail(count,'abcdef')),expected)
    for count in (Count(-1),NamedCount.NEGATIVE):
        raises(ValueError,lambda:tail(count,iter('abcdef')))
        raises(ValueError,lambda:tail(count,'abcdef'))


def index_only_protocol_observation():
    observations={}
    for n in (-1,0,2,8):
        entry={}
        for name,function in [('native_deque',lambda:list(deque(iter('abc'),maxlen=IndexCount(n)))),
                              ('tail_unsized',lambda:list(tail(IndexCount(n),iter('abc'))))]:
            try:
                entry[name]={'result':function()}
            except Exception as exc:
                entry[name]={'error':type(exc).__name__}
        observations[str(n)]=entry
    return observations


def iterator_protocol_ownership_and_timing():
    class Traced:
        def __init__(self,values):
            self.values=values
            self.pulls=[]
        def __iter__(self):
            for value in self.values:
                self.pulls.append(value)
                yield value
    class Sized(Traced):
        def __len__(self):
            return len(self.values)
    first,second,third=object(),object(),object()
    values=[first,second,third]
    for cls,eager in ((Sized,False),(Traced,True)):
        source=cls(values)
        exported=tail(2,source)
        assert iter(exported) is exported
        eq(len(source.pulls),3 if eager else 0)
        actual=list(exported)
        assert actual[0] is second and actual[1] is third
        eq(len(source.pulls),3)
        eq(list(exported),[])
        eq([id(value) for value in values],[id(first),id(second),id(third)])


def unexpected_input_errors():
    for clsname in ('sized','unsized'):
        failure=RuntimeError('source failed')
        pulls=[]
        class Broken:
            def __iter__(self):
                pulls.append('value')
                yield 'a'
                pulls.append('failure')
                raise failure
        class Sized(Broken):
            def __len__(self):
                return 2
        source=Sized() if clsname=='sized' else Broken()
        if clsname=='sized':
            exported=tail(2,source)
            eq(pulls,[])
            raises(RuntimeError,lambda:list(exported),failure)
        else:
            raises(RuntimeError,lambda:tail(2,source),failure)
        eq(pulls,['value','failure'])
    failure=KeyboardInterrupt('source interrupted')
    class Interrupted:
        def __iter__(self):
            raise failure
    raises(KeyboardInterrupt,lambda:tail(1,Interrupted()),failure)


def len_fallback_and_errors():
    class UnsizedLike:
        def __len__(self):
            raise TypeError('no length available')
        def __iter__(self):
            return iter('abcd')
    eq(list(tail(2,UnsizedLike())),['c','d'])
    failure=RuntimeError('length source failed')
    class BadLength:
        def __len__(self):
            raise failure
        def __iter__(self):
            raise AssertionError('unexpected fallback after RuntimeError')
    raises(RuntimeError,lambda:tail(2,BadLength()),failure)


def public_keyword_and_bool_counts():
    eq(list(tail(n=2,iterable='abc')),['b','c'])
    eq(list(tail(2,iterable=iter('abc'))),['b','c'])
    for n,expected in ((False,[]),(True,['c'])):
        eq(list(tail(n,'abc')),expected)
        eq(list(tail(n,iter('abc'))),expected)


def negative_error_precedence_observation():
    events=[]
    failure=RuntimeError('length query failed')
    class Source:
        def __len__(self):
            events.append('len')
            raise failure
        def __iter__(self):
            events.append('iter')
            return iter('abc')
    try:
        tail(-1,Source())
    except Exception as exc:
        return {'error':type(exc).__name__,'original_source_error':exc is failure,'events':events}
    return {'returned_without_error':True,'events':events}


check('negative_plain_integer_sized_unsized_is_valueerror',negative_plain_integers)
check('zero_length_sized_unsized',zero_counts)
check('ordinary_and_oversize_sized_unsized_outputs',ordinary_counts_and_oversize)
check('supported_int_subclass_intenum_counts',integer_subclass_counts)
check('index_only_count_native_baseline_observation',index_only_protocol_observation)
check('iterator_protocol_original_references_lazy_eager_timing',iterator_protocol_ownership_and_timing)
check('unexpected_source_errors_identity_and_timing',unexpected_input_errors)
check('typeerror_len_fallback_other_len_error_propagation',len_fallback_and_errors)
check('public_keyword_and_bool_length_forms',public_keyword_and_bool_counts)
check('negative_source_error_precedence_observation',negative_error_precedence_observation)
print(json.dumps({'module':recipes.__file__,'results':results},ensure_ascii=True))
